import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-javascript-get-nested-object-property-from-path-string":{"intro":"In this lab, we will explore how to retrieve nested object properties using a given path string in JavaScript. We will learn how to use various array methods such as map(), filter(), and reduce() to extract specific values from complex objects. This skill is essential for working with large datasets and APIs that return nested JSON objects.","steps":[{"title":"Get Nested Object Property From Path String","body":["How to Retrieve Nested Object Properties from Path Strings","The following function retrieves a set of properties from an object by using selectors specified in a path string. To achieve this, follow these steps:","• Use Array.prototype.map() to iterate through each selector, and apply String.prototype.replace() to replace square brackets with dots. • Use String.prototype.split() to split each selector into an array of strings. • Use Array.prototype.filter() to remove any empty values. • Use Array.prototype.reduce() to retrieve the value indicated by each selector.","You can use this function to retrieve values from a nested object using a path string. Here is an example:"],"code":[{"lang":"js","text":"const get = (from, ...selectors) =>\n  [...selectors].map((s) =>\n    s\n      .replace(/\\[([^\\[\\]]*)\\]/g, \".$1.\")\n      .split(\".\")\n      .filter((t) => t !== \"\")\n      .reduce((prev, cur) => prev && prev[cur], from)\n  );"},{"lang":"js","text":"const obj = {\n  selector: { to: { val: \"val to select\" } },\n  target: [1, 2, { a: \"test\" }]\n};\nget(obj, \"selector.to.val\", \"target[0]\", \"target[2].a\");\n// ['val to select', 1, 'test']"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const obj = {\n  selector: { to: { val: \"val to select\" } },\n  target: [1, 2, { a: \"test\" }]\n};\nget(obj, \"selector.to.val\", \"target[0]\", \"target[2].a\");\n// ['val to select', 1, 'test']"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-get-nested-value-in-object":{"intro":"In this lab, we will explore how to get nested values in JavaScript objects using a function called dig. This function can be used to retrieve a specific value from a complex nested object, making it easier to access the necessary information. Through this lab, you will learn how to use the in operator and the reduce() method to traverse through nested objects and find the target value.","steps":[{"title":"Get Nested Value in Object","body":["How to Get a Nested Value in a JSON Object","To retrieve a target value from a nested JSON object based on a given key, follow these steps:","Here is the code for the dig function:","To use the dig function, first create a JSON object with nested levels, like this:"],"code":[{"lang":"js","text":"const dig = (obj, target) =>\n  target in obj\n    ? obj[target]\n    : Object.values(obj).reduce((acc, val) => {\n        if (acc !== undefined) return acc;\n        if (typeof val === \"object\") return dig(val, target);\n      }, undefined);"},{"lang":"js","text":"const data = {\n  level1: {\n    level2: {\n      level3: \"some data\"\n    }\n  }\n};"},{"lang":"js","text":"dig(data, \"level3\"); // 'some data'\ndig(data, \"level4\"); // undefined"}]}],"commands":[],"reference":[{"path":"reference.js","text":"dig(data, \"level3\"); // 'some data'\ndig(data, \"level4\"); // undefined"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-url-parameters-as-object":{"intro":"In this lab, we will explore how to extract and map URL parameters into a JavaScript object using regular expressions and array methods. We will learn how to use String.prototype.match() to obtain all key-value pairs and Array.prototype.reduce() to transform them into a single object. By the end of this lab, you will have a better understanding of how to work with URLs and extract useful information from them.","steps":[{"title":"URL Parameters as Object","body":["To create an object that contains the parameters of the current URL, follow these steps:","You can use this function with any URL to get an object with its parameters. Here are some examples:"],"code":[{"lang":"js","text":"const getURLParameters = (url) =>\n  (url.match(/([^?=&]+)(=([^&]*))/g) || []).reduce(\n    (a, v) => (\n      (a[v.slice(0, v.indexOf(\"=\"))] = v.slice(v.indexOf(\"=\") + 1)),\n      a\n    ),\n    {}\n  );"},{"lang":"js","text":"getURLParameters(\"google.com\"); // {}\ngetURLParameters(\"http://url.com/page?name=Adam&surname=Smith\");\n// {name: 'Adam', surname: 'Smith'}"}]}],"commands":[],"reference":[{"path":"reference.js","text":"getURLParameters(\"google.com\"); // {}\ngetURLParameters(\"http://url.com/page?name=Adam&surname=Smith\");\n// {name: 'Adam', surname: 'Smith'}"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-group-data-from-multiple-arrays":{"intro":"In this lab, we will be exploring how to group array elements based on their position in the original arrays. We will be using the zip() function which takes in multiple arrays and returns a new array containing sub-arrays of elements from each input array, grouped by their position. This is a useful technique in data processing and analysis, and can be used to combine data from multiple sources into a single data structure for further analysis.","steps":[{"title":"Group Array Elements","body":["To group elements of arrays based on their position in the original arrays, use the zip function provided below."],"code":[{"lang":"js","text":"const zip = (...arrays) => {\n  const maxLength = Math.max(...arrays.map((x) => x.length));\n  return Array.from({ length: maxLength }).map((_, i) => {\n    return Array.from({ length: arrays.length }, (_, k) => arrays[k][i]);\n  });\n};"},{"lang":"js","text":"zip([\"a\", \"b\"], [1, 2], [true, false]); // [['a', 1, true], ['b', 2, false]]\nzip([\"a\"], [1, 2], [true, false]); // [['a', 1, true], [undefined, 2, false]]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"zip([\"a\", \"b\"], [1, 2], [true, false]); // [['a', 1, true], ['b', 2, false]]\nzip([\"a\"], [1, 2], [true, false]); // [['a', 1, true], [undefined, 2, false]]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-group-array-into-object":{"intro":"In this lab, we will explore how to group an array into an object using JavaScript. Specifically, we will use the Array.prototype.reduce() method to associate properties to values in an object, given an array of valid property identifiers and an array of values. We will also learn how to handle cases where the length of the two arrays differ. By the end of the lab, you will have gained a deeper understanding of how to manipulate objects and arrays in JavaScript.","steps":[{"title":"Group Array Into Object","body":["How to Group an Array into an Object","To group an array into an object, follow these steps:","Here is an example code snippet that demonstrates how to group an array into an object:"],"code":[{"lang":"js","text":"const zipObject = (props, values) =>\n  props.reduce((obj, prop, index) => ((obj[prop] = values[index]), obj), {});\n\nzipObject([\"a\", \"b\", \"c\"], [1, 2]); // {a: 1, b: 2, c: undefined}\nzipObject([\"a\", \"b\"], [1, 2, 3]); // {a: 1, b: 2}"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const zipObject = (props, values) =>\n  props.reduce((obj, prop, index) => ((obj[prop] = values[index]), obj), {});\n\nzipObject([\"a\", \"b\", \"c\"], [1, 2]); // {a: 1, b: 2, c: undefined}\nzipObject([\"a\", \"b\"], [1, 2, 3]); // {a: 1, b: 2}"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-number-has-decimal-digits":{"intro":"In this lab, we will explore the concept of checking if a number has any decimal digits using JavaScript. We will learn how to use the modulo operator to check if a number is divisible by one and return the result. Through practical examples and exercises, we will gain a better understanding of how to implement this concept in our JavaScript programs.","steps":[{"title":"Number Has Decimal Digits","body":["How to Check if a Number Has Decimal Digits","To check if a number has any decimal digits, you can use the modulo operator in JavaScript. Follow these steps:","Here's an example code to check if a number has decimal digits:","You can test the function by calling it with different numbers, like this:"],"code":[{"lang":"js","text":"const hasDecimals = (num) => num % 1 !== 0;"},{"lang":"js","text":"hasDecimals(1); // false\nhasDecimals(1.001); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"hasDecimals(1); // false\nhasDecimals(1.001); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-hash-string-into-number":{"intro":"In this lab, we will explore how to hash a string into a whole number using the SDBM algorithm. We will use String.prototype.split() and Array.prototype.reduce() to create a hash of the input string, utilizing bit shifting. The purpose of this lab is to introduce you to the concept of hashing and how it can be used to generate unique identifiers for data.","steps":[{"title":"Hash String Into Number","body":["How to Hash a String into a Number Using JavaScript","To hash an input string into a whole number using JavaScript, follow these steps:","• To test the function, call it with a string argument:","This will return the hash value for the input string \"name\"."],"code":[{"lang":"js","text":"const sdbm = (str) => {\n  let arr = str.split(\"\");\n  return arr.reduce(\n    (hashCode, currentVal) =>\n      (hashCode =\n        currentVal.charCodeAt(0) +\n        (hashCode << 6) +\n        (hashCode << 16) -\n        hashCode),\n    0\n  );\n};"},{"lang":"js","text":"sdbm(\"name\"); // -3521204949"}]}],"commands":[],"reference":[{"path":"reference.js","text":"sdbm(\"name\"); // -3521204949"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-implementing-heapsort-algorithm-in-javascrip":{"intro":"In this lab, we will explore the implementation of the heapsort algorithm in JavaScript. Heapsort is a comparison-based sorting algorithm that works by dividing an array into a sorted and an unsorted region, and iteratively shrinking the unsorted region by extracting the largest element and moving that to the sorted region. Through this lab, you will gain a deeper understanding of how the heapsort algorithm works and how to implement it using recursion and closures in JavaScript.","steps":[{"title":"Heap Sort","body":["• Use recursion in the function. • Use the spread operator (...) to clone the original array, arr. • Use closures to declare a variable, l, and a function heapify. • Use a for loop and Math.floor() in combination with heapify to create a max heap from the array. • Use a for loop to repeatedly narrow down the considered range, using heapify and swapping values as necessary to sort the cloned array."],"code":[{"lang":"js","text":"const heapsort = (arr) => {\n  const a = [...arr];\n  let l = a.length;\n  const heapify = (a, i) => {\n    const left = 2 * i + 1;\n    const right = 2 * i + 2;\n    let max = i;\n    if (left < l && a[left] > a[max]) max = left;\n    if (right < l && a[right] > a[max]) max = right;\n    if (max !== i) {\n      [a[max], a[i]] = [a[i], a[max]];\n      heapify(a, max);\n    }\n  };\n  for (let i = Math.floor(l / 2); i >= 0; i -= 1) heapify(a, i);\n  for (let i = a.length - 1; i > 0; i--) {\n    [a[0], a[i]] = [a[i], a[0]];\n    l--;\n    heapify(a, 0);\n  }\n  return a;\n};"},{"lang":"js","text":"heapsort([6, 3, 4, 1]); // [1, 3, 4, 6]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"heapsort([6, 3, 4, 1]); // [1, 3, 4, 6]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-convert-hexadecimal-to-rgb-string":{"intro":"In this lab, we will explore how to convert a hexadecimal color code to an rgb() or rgba() string using JavaScript. We will learn how to use bitwise operators and masking to extract the RGB values from the hex code. The lab will also cover how to handle 3-digit and 6-digit hex codes and how to incorporate an alpha value into the resulting string.","steps":[{"title":"Hex to RGB","body":["To convert a hexadecimal color code (with or without a # prefix) to an RGB string, follow these steps:","Here is the JavaScript code for the conversion:","You can use the hexToRGB function with the following examples:"],"code":[{"lang":"js","text":"const hexToRGB = (hex) => {\n  let alpha = false,\n    h = hex.slice(hex.startsWith(\"#\") ? 1 : 0);\n  if (h.length === 3) h = [...h].map((x) => x + x).join(\"\");\n  else if (h.length === 8) alpha = true;\n  h = parseInt(h, 16);\n  return (\n    \"rgb\" +\n    (alpha ? \"a\" : \"\") +\n    \"(\" +\n    (h >>> (alpha ? 24 : 16)) +\n    \", \" +\n    ((h & (alpha ? 0x00ff0000 : 0x00ff00)) >>> (alpha ? 16 : 8)) +\n    \", \" +\n    ((h & (alpha ? 0x0000ff00 : 0x0000ff)) >>> (alpha ? 8 : 0)) +\n    (alpha ? `, ${h & 0x000000ff}` : \"\") +\n    \")\"\n  );\n};"},{"lang":"js","text":"hexToRGB(\"#27ae60ff\"); // 'rgba(39, 174, 96, 255)'\nhexToRGB(\"27ae60\"); // 'rgb(39, 174, 96)'\nhexToRGB(\"#fff\"); // 'rgb(255, 255, 255)'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"hexToRGB(\"#27ae60ff\"); // 'rgba(39, 174, 96, 255)'\nhexToRGB(\"27ae60\"); // 'rgb(39, 174, 96)'\nhexToRGB(\"#fff\"); // 'rgb(255, 255, 255)'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-exploring-hsb-to-rgb-color-conversion":{"intro":"In this lab, we will explore the HSB to RGB color conversion process using JavaScript. We will learn how to convert HSB color values to RGB format using a formula and convert the output to the appropriate range of values. By the end of the lab, you will have a better understanding of color models and how to work with them in JavaScript.","steps":[{"title":"HSB to RGB","body":["To convert a HSB color tuple to RGB format, follow these steps:","Here's the code that you can use to convert HSB to RGB:","For example, if you want to convert the HSB color tuple (18, 81, 99) to RGB format, you can use the following code:"],"code":[{"lang":"js","text":"const HSBToRGB = (h, s, b) => {\n  s /= 100;\n  b /= 100;\n  const k = (n) => (n + h / 60) % 6;\n  const f = (n) => b * (1 - s * Math.max(0, Math.min(k(n), 4 - k(n), 1)));\n  return [255 * f(5), 255 * f(3), 255 * f(1)];\n};"},{"lang":"js","text":"HSBToRGB(18, 81, 99); // [252.45, 109.31084999999996, 47.965499999999984]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"HSBToRGB(18, 81, 99); // [252.45, 109.31084999999996, 47.965499999999984]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-javascript-hsl-to-rgb-conversion":{"intro":"In this lab, we will delve into the world of JavaScript programming and learn about HSL to RGB conversion. You will be introduced to the HSL to RGB conversion formula, and how to use it to convert HSL color tuples to RGB format. By the end of this lab, you will have gained a deeper understanding of how to work with color in JavaScript and how to manipulate HSL values to create beautiful color schemes.","steps":[{"title":"HSL to RGB","body":["Convert HSL to RGB using JavaScript","To convert a color tuple in HSL format to RGB, follow these steps:","Here is the JavaScript code for the HSL to RGB conversion formula:","To use the function, provide the H, S, and L values as arguments:"],"code":[{"lang":"js","text":"const HSLToRGB = (h, s, l) => {\n  s /= 100;\n  l /= 100;\n  const k = (n) => (n + h / 30) % 12;\n  const a = s * Math.min(l, 1 - l);\n  const f = (n) =>\n    l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));\n  return [255 * f(0), 255 * f(8), 255 * f(4)];\n};"},{"lang":"js","text":"HSLToRGB(13, 100, 11); // [56.1, 12.155, 0]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"HSLToRGB(13, 100, 11); // [56.1, 12.155, 0]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-hertz-frequency-of-function":{"intro":"In this lab, we will dive into measuring the performance of JavaScript functions using the concept of Hertz frequency. We will learn how to use the performance.now() method to calculate the time elapsed executing a function and how to determine the number of cycles per second. Through practical examples and exercises, we will explore the differences in performance between different implementations of the same function.","steps":[{"title":"Hertz Frequency of Function","body":["Function Frequency Calculation","To measure the frequency of a function execution per second (hz/hertz), use the hz function. You can do this by following these steps:","Here's an example of using the hz function to compare the performance of two functions that calculate the sum of an array of 10,000 numbers:","In this example, sumReduce is faster than sumForLoop because it has a lower frequency of function execution."],"code":[{"lang":"js","text":"const hz = (fn, iterations = 100) => {\n  const before = performance.now();\n  for (let i = 0; i < iterations; i++) fn();\n  return (1000 * iterations) / (performance.now() - before);\n};"},{"lang":"js","text":"const numbers = Array(10000)\n  .fill()\n  .map((_, i) => i);\n\nconst sumReduce = () => numbers.reduce((acc, n) => acc + n, 0);\nconst sumForLoop = () => {\n  let sum = 0;\n  for (let i = 0; i < numbers.length; i++) sum += numbers[i];\n  return sum;\n};\n\nMath.round(hz(sumReduce)); // 572\nMath.round(hz(sumForLoop)); // 4784"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const numbers = Array(10000)\n  .fill()\n  .map((_, i) => i);\n\nconst sumReduce = () => numbers.reduce((acc, n) => acc + n, 0);\nconst sumForLoop = () => {\n  let sum = 0;\n  for (let i = 0; i < numbers.length; i++) sum += numbers[i];\n  return sum;\n};\n\nMath.round(hz(sumReduce)); // 572\nMath.round(hz(sumForLoop)); // 4784"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-case-insensitive-substring-search":{"intro":"In this lab, we will be exploring how to perform a case-insensitive substring search in JavaScript. We will use the RegExp constructor and the 'i' flag to create a regular expression that can match the given search string, ignoring the case. By the end of this lab, you will have a better understanding of how to search for substrings without having to worry about case-sensitivity.","steps":[{"title":"Case-Insensitive Substring Search","body":["Case-Insensitive Substring Search","To check if a string contains a substring regardless of the case, follow these steps:","• Use the RegExp constructor with the 'i' flag to create a regular expression that matches the given searchString, ignoring the case. • Use RegExp.prototype.test() to check if the string contains the substring.","Here is an example code snippet:"],"code":[{"lang":"js","text":"const includesCaseInsensitive = (str, searchString) =>\n  new RegExp(searchString, \"i\").test(str);"},{"lang":"js","text":"includesCaseInsensitive(\"Blue Whale\", \"blue\"); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"includesCaseInsensitive(\"Blue Whale\", \"blue\"); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-indent-string-formatting-in-javascript":{"intro":"In this lab, we will dive into the indentString function in JavaScript. This function allows us to easily indent each line in a given string by a specified amount. with this function, we can format strings for better readability and organization in our code.","steps":[{"title":"Indent String","body":["A Function to Indent Strings in JavaScript","To add indentation to each line in a given string, you can use the indentString() function in JavaScript. This function takes three arguments: str, count, and indent.","• The str argument represents the string you want to indent. • The count argument determines how many times you want to indent each line. • The indent argument is optional and represents the character you want to use for indentation. If you don't provide it, the default value is a single space character (' ').","Here is the code for the indentString() function:"],"code":[{"lang":"js","text":"const indentString = (str, count, indent = \" \") =>\n  str.replace(/^/gm, indent.repeat(count));"},{"lang":"js","text":"indentString(\"Lorem\\nIpsum\", 2); // '  Lorem\\n  Ipsum'\nindentString(\"Lorem\\nIpsum\", 2, \"_\"); // '__Lorem\\n__Ipsum'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"indentString(\"Lorem\\nIpsum\", 2); // '  Lorem\\n  Ipsum'\nindentString(\"Lorem\\nIpsum\", 2, \"_\"); // '__Lorem\\n__Ipsum'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-index-of-all-matches":{"intro":"In this lab, we will be exploring the indexOfAll function in JavaScript. This function allows us to find all indexes of a given value in an array. By using the Array.prototype.reduce() method, we can easily loop over the elements of an array and store the indexes for matching elements. This lab will provide hands-on experience with this useful function and its implementation in JavaScript.","steps":[{"title":"Index of All Matches","body":["To find all indexes of val in an array, use Array.prototype.reduce() to loop over the elements and store the indexes for matching elements. If val never occurs, an empty array is returned.","This is an index of all matches."],"code":[{"lang":"js","text":"const indexOfAll = (arr, val) =>\n  arr.reduce((acc, el, i) => (el === val ? [...acc, i] : acc), []);"},{"lang":"js","text":"indexOfAll([1, 2, 3, 1, 2, 3], 1); // [0, 3]\nindexOfAll([1, 2, 3], 4); // []"}]}],"commands":[],"reference":[{"path":"reference.js","text":"indexOfAll([1, 2, 3, 1, 2, 3], 1); // [0, 3]\nindexOfAll([1, 2, 3], 4); // []"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-index-of-substrings":{"intro":"In this lab, we will explore the fundamentals of JavaScript programming language. You will learn the basic syntax, data types, functions, and control structures of JavaScript. By the end of the lab, you will be able to write simple programs using JavaScript and have a solid understanding of the language. This lab is designed for beginners who have no prior experience in programming or JavaScript.","steps":[{"title":"Index of Substrings","body":["To find all the indexes of a substring in a given string, follow these steps:","Here's an example code to implement the above steps:","You can test the function with the following code:"],"code":[{"lang":"js","text":"const indexOfSubstrings = function* (str, searchValue) {\n  let i = 0;\n  while (true) {\n    const r = str.indexOf(searchValue, i);\n    if (r !== -1) {\n      yield r;\n      i = r + 1;\n    } else return;\n  }\n};"},{"lang":"js","text":"[...indexOfSubstrings(\"tiktok tok tok tik tok tik\", \"tik\")]; // [0, 15, 23]\n[...indexOfSubstrings(\"tutut tut tut\", \"tut\")]; // [0, 2, 6, 10]\n[...indexOfSubstrings(\"hello\", \"hi\")]; // []"}]}],"commands":[],"reference":[{"path":"reference.js","text":"[...indexOfSubstrings(\"tiktok tok tok tik tok tik\", \"tik\")]; // [0, 15, 23]\n[...indexOfSubstrings(\"tutut tut tut\", \"tut\")]; // [0, 2, 6, 10]\n[...indexOfSubstrings(\"hello\", \"hi\")]; // []"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-initialize-array-until":{"intro":"In this lab, we will explore the concept of initializing and filling an array with values generated by a function until a specific condition is met. We will be using the initializeArrayUntil function which takes two arguments: conditionFn and mapFn. Through this lab, you will gain a deeper understanding of how to use this function to generate arrays with custom values and conditions.","steps":[{"title":"Initialize Array Until","body":["How to Initialize an Array Until a Condition is Met","Here are the steps to initialize and fill an array with values generated by a function until a certain condition is met:","• Create an empty array arr, an index variable i, and an element el. • Use a do...while loop to add elements to the array using the mapFn function until the conditionFn function returns true for the given index i and element el. • The conditionFn function takes three arguments: the current index, the previous element, and the array itself. • The mapFn function takes three arguments: the current index, the current element, and the array itself.","To use the initializeArrayUntil function, provide two functions as arguments:"],"code":[{"lang":"js","text":"const initializeArrayUntil = (conditionFn, mapFn) => {\n  const arr = [];\n  let i = 0;\n  let el = undefined;\n  do {\n    el = mapFn(i, el, arr);\n    arr.push(el);\n    i++;\n  } while (!conditionFn(i, el, arr));\n  return arr;\n};"},{"lang":"js","text":"initializeArrayUntil(\n  (i, val) => val > 10, //conditionFn\n  (i, val, arr) => (i <= 1 ? 1 : val + arr[i - 2]) //mapFn\n); // [1, 1, 2, 3, 5, 8, 13]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"initializeArrayUntil(\n  (i, val) => val > 10, //conditionFn\n  (i, val, arr) => (i <= 1 ? 1 : val + arr[i - 2]) //mapFn\n); // [1, 1, 2, 3, 5, 8, 13]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-initialize-array-while":{"intro":"In this lab, we will explore the concept of initializing and filling an array with values generated by a function, while a specified condition is met. We will use the initializeArrayWhile function which takes two functions as arguments, a condition function and a mapping function. This lab will help you understand how to create a customized array based on a specific condition and mapping function.","steps":[{"title":"Initialize Array While","body":["How to Initialize and Fill an Array with a While Loop in JavaScript","The initializeArrayWhile function initializes and fills an array with values generated by a function while a condition is met. Here's how it works:","• Create an empty array called arr, an index variable called i, and an element called el. • Use a while loop to add elements to the array using the mapFn function, as long as the conditionFn function returns true for the given index i and element el. • The conditionFn function takes three arguments: the current index, the previous element, and the array itself. • The mapFn function takes three arguments: the current index, the current element, and the array itself. • The initializeArrayWhile function returns the array.","You can use the initializeArrayWhile function to initialize and fill an array with values. For example:"],"code":[{"lang":"js","text":"const initializeArrayWhile = (conditionFn, mapFn) => {\n  const arr = [];\n  let i = 0;\n  let el = mapFn(i, undefined, arr);\n  while (conditionFn(i, el, arr)) {\n    arr.push(el);\n    i++;\n    el = mapFn(i, el, arr);\n  }\n  return arr;\n};"},{"lang":"js","text":"initializeArrayWhile(\n  (i, val) => val < 10,\n  (i, val, arr) => (i <= 1 ? 1 : val + arr[i - 2])\n); // [1, 1, 2, 3, 5, 8]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"initializeArrayWhile(\n  (i, val) => val < 10,\n  (i, val, arr) => (i <= 1 ? 1 : val + arr[i - 2])\n); // [1, 1, 2, 3, 5, 8]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-initialize-array-with-range":{"intro":"In this lab, we will explore the implementation of a function called initializeArrayWithRange in JavaScript. This function initializes an array containing the numbers in a specified range, with the option to include a step value. We will learn how to use Array.from(), the map() function, and default parameter values to create a flexible and reusable function for generating arrays with a range of values.","steps":[{"title":"Initialize Array with Range","body":["Function to Initialize Array with Range","To initialize an array with a range of numbers, use the following function:","This function takes three arguments: end (required), start (optional, default value is 0), and step (optional, default value is 1). It returns an array containing the numbers in the specified range, where start and end are inclusive with their common difference step.","To use this function, simply call it with the desired range parameters:"],"code":[{"lang":"js","text":"const initializeArrayWithRange = (end, start = 0, step = 1) => {\n  const length = Math.ceil((end - start + 1) / step);\n  return Array.from({ length }, (_, i) => i * step + start);\n};"},{"lang":"js","text":"initializeArrayWithRange(5); // [0, 1, 2, 3, 4, 5]\ninitializeArrayWithRange(7, 3); // [3, 4, 5, 6, 7]\ninitializeArrayWithRange(9, 0, 2); // [0, 2, 4, 6, 8]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"initializeArrayWithRange(5); // [0, 1, 2, 3, 4, 5]\ninitializeArrayWithRange(7, 3); // [3, 4, 5, 6, 7]\ninitializeArrayWithRange(9, 0, 2); // [0, 2, 4, 6, 8]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-initialize-array-with-reversed-range":{"intro":"In this lab, we will explore how to initialize an array with reversed range using JavaScript. We will learn how to use the Array.from() and Array.prototype.map() methods to create an array that contains numbers in a specified range, but in reverse order. We will also see how to set default values for the start and step parameters and use them to generate the desired output.","steps":[{"title":"Initialize Array with Reversed Range","body":["How to Initialize an Array with a Reversed Range in JavaScript","To initialize an array with a reversed range in JavaScript, use the following function:","This function creates an array containing the numbers in the specified range in reverse order. The start and end parameters are inclusive, and the step parameter specifies the common difference between the numbers in the range.","To use the function, call it with the desired end, start, and step values as arguments, like this:"],"code":[{"lang":"js","text":"const initializeArrayWithRangeRight = (end, start = 0, step = 1) =>\n  Array.from({ length: Math.ceil((end + 1 - start) / step) }).map(\n    (v, i, arr) => (arr.length - i - 1) * step + start\n  );"},{"lang":"js","text":"initializeArrayWithRangeRight(5); // [5, 4, 3, 2, 1, 0]\ninitializeArrayWithRangeRight(7, 3); // [7, 6, 5, 4, 3]\ninitializeArrayWithRangeRight(9, 0, 2); // [8, 6, 4, 2, 0]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"initializeArrayWithRangeRight(5); // [5, 4, 3, 2, 1, 0]\ninitializeArrayWithRangeRight(7, 3); // [7, 6, 5, 4, 3]\ninitializeArrayWithRangeRight(9, 0, 2); // [8, 6, 4, 2, 0]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-initialize-array-with-values":{"intro":"In this lab, we will explore how to initialize and fill an array with specific values in JavaScript. We will use the Array() constructor and the Array.prototype.fill() method to create and populate the array. By the end of the lab, you will have a deeper understanding of how to create and manipulate arrays in JavaScript.","steps":[{"title":"Initialize Array with Values","body":["Function to Initialize an Array with Specified Values","This function initializes an array with the specified values:","• Use the Array() constructor to create an array of the desired length. • Use Array.prototype.fill() to fill it with the desired values. • If no value is specified, it defaults to 0."],"code":[{"lang":"js","text":"const initializeArrayWithValues = (length, value = 0) =>\n  Array(length).fill(value);"},{"lang":"js","text":"initializeArrayWithValues(5, 2); // [2, 2, 2, 2, 2]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"initializeArrayWithValues(5, 2); // [2, 2, 2, 2, 2]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-initialize-mapped-array":{"intro":"In this lab, we will explore how to initialize and fill an array with specified values using a mapping function in JavaScript. We will be using the Array() constructor to create an array of the desired length and the Array.prototype.fill() method to fill it with null values. Additionally, we will be using the Array.prototype.map() method to fill the array with the desired values using the provided function.","steps":[{"title":"Initialize Mapped Array","body":["Initializing a Mapped Array in JavaScript","To initialize a mapped array in JavaScript, follow these steps:","Here's an example code snippet:","You can use the initializeMappedArray function to create a mapped array with the desired values:"],"code":[{"lang":"js","text":"const initializeMappedArray = (n, mapFn = (_, i) => i) =>\n  Array(n).fill(null).map(mapFn);"},{"lang":"js","text":"initializeMappedArray(5); // [0, 1, 2, 3, 4]\ninitializeMappedArray(5, (i) => `item ${i + 1}`);\n// ['item 1', 'item 2', 'item 3', 'item 4', 'item 5']"}]}],"commands":[],"reference":[{"path":"reference.js","text":"initializeMappedArray(5); // [0, 1, 2, 3, 4]\ninitializeMappedArray(5, (i) => `item ${i + 1}`);\n// ['item 1', 'item 2', 'item 3', 'item 4', 'item 5']"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-initialize-n-dimensional-array":{"intro":"In this lab, we will explore how to create n-dimensional arrays with a given value using recursion in JavaScript. We will use the Array.from() and Array.prototype.map() methods to generate rows where each is a new array initialized using initializeNDArray(). By the end of this lab, you will have a solid understanding of how to create multi-dimensional arrays in JavaScript and how to use recursion to accomplish this task.","steps":[{"title":"Initialize N-Dimensional Array","body":["How to Initialize an N-Dimensional Array in JavaScript","To create an N-dimensional array in JavaScript, you can use the initializeNDArray function. This function takes a value and any number of dimensions as arguments and returns a new array initialized with that value.","To use initializeNDArray, you can follow these steps:","Here's the code for the initializeNDArray function:"],"code":[{"lang":"js","text":"const initializeNDArray = (val, ...args) =>\n  args.length === 0\n    ? val\n    : Array.from({ length: args[0] }).map(() =>\n        initializeNDArray(val, ...args.slice(1))\n      );"},{"lang":"js","text":"initializeNDArray(1, 3); // [1, 1, 1]\ninitializeNDArray(5, 2, 2, 2); // [[[5, 5], [5, 5]], [[5, 5], [5, 5]]]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"initializeNDArray(1, 3); // [1, 1, 1]\ninitializeNDArray(5, 2, 2, 2); // [[[5, 5], [5, 5]], [[5, 5], [5, 5]]]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-insert-value-at-array-index":{"intro":"In this lab, we will explore the concept of inserting values into an array at a specified index using JavaScript. You will learn how to use the Array.prototype.splice() method to insert values after a given index with a delete count of 0. This lab will provide you with hands-on experience in manipulating arrays in JavaScript and help you understand how to mutate the original array while inserting new values.","steps":[{"title":"Insert Value at Array Index","body":["How to Insert a Value at a Specific Index in an Array using JavaScript","To insert a value at a specific index in an array using JavaScript, follow these steps:","Here's an example of the insertAt function in action:","In the example above, the insertAt function is used to insert the value 5 after the second index of the myArray array, and to insert the values 4, 6, and 8 after the first index of the otherArray array."],"code":[{"lang":"js","text":"const insertAt = (arr, i, ...v) => {\n  arr.splice(i + 1, 0, ...v);\n  return arr;\n};\n\nlet myArray = [1, 2, 3, 4];\ninsertAt(myArray, 2, 5); // myArray = [1, 2, 3, 5, 4]\n\nlet otherArray = [2, 10];\ninsertAt(otherArray, 0, 4, 6, 8); // otherArray = [2, 4, 6, 8, 10]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const insertAt = (arr, i, ...v) => {\n  arr.splice(i + 1, 0, ...v);\n  return arr;\n};\n\nlet myArray = [1, 2, 3, 4];\ninsertAt(myArray, 2, 5); // myArray = [1, 2, 3, 5, 4]\n\nlet otherArray = [2, 10];\ninsertAt(otherArray, 0, 4, 6, 8); // otherArray = [2, 4, 6, 8, 10]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-insertion-index-in-sorted-array":{"intro":"In this lab, we will explore the fundamentals of JavaScript programming. Through a series of exercises and challenges, we will cover topics such as data types, variables, functions, and control flow. By the end of this lab, you will have a strong foundation in JavaScript programming and be equipped with the skills to tackle more advanced concepts. Get ready to dive into the exciting world of JavaScript!","steps":[{"title":"Insertion Index in Sorted Array","body":["How to Find Insertion Index in Sorted Array","To find the lowest index at which a value should be inserted into a sorted array, follow these steps:","• Check if the array is sorted in descending order. • Use Array.prototype.findIndex() method to find the appropriate index where the element should be inserted.","Here's the code to implement this:"],"code":[{"lang":"js","text":"const sortedIndex = (arr, n) => {\n  const isDescending = arr[0] > arr[arr.length - 1];\n  const index = arr.findIndex((el) => (isDescending ? n >= el : n <= el));\n  return index === -1 ? arr.length : index;\n};"},{"lang":"js","text":"sortedIndex([5, 3, 2, 1], 4); // Output: 1\nsortedIndex([30, 50], 40); // Output: 1"}]}],"commands":[],"reference":[{"path":"reference.js","text":"sortedIndex([5, 3, 2, 1], 4); // Output: 1\nsortedIndex([30, 50], 40); // Output: 1"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-implementing-insertion-sort-in-javascript":{"intro":"In this lab, we will explore the implementation of the insertion sort algorithm in JavaScript. We will learn how to sort an array of numbers using this algorithm and understand the logic behind it. By the end of this lab, you will be able to use the insertion sort algorithm to efficiently sort arrays in your JavaScript projects.","steps":[{"title":"Insertion Sort","body":["Insertion Sort Algorithm in JavaScript","• Use Array.prototype.reduce() to iterate over all the elements in the given array. • If the length of the accumulator is 0, add the current element to it. • Use Array.prototype.some() to iterate over the results in the accumulator until the correct position is found. • Use Array.prototype.splice() to insert the current element into the accumulator.","Here's the code to implement insertion sort in JavaScript:","You can test the algorithm with the following code:"],"code":[{"lang":"js","text":"const insertionSort = (arr) =>\n  arr.reduce((acc, x) => {\n    if (!acc.length) return [x];\n    acc.some((y, j) => {\n      if (x <= y) {\n        acc.splice(j, 0, x);\n        return true;\n      }\n      if (x > y && j === acc.length - 1) {\n        acc.splice(j + 1, 0, x);\n        return true;\n      }\n      return false;\n    });\n    return acc;\n  }, []);"},{"lang":"js","text":"insertionSort([6, 3, 4, 1]); // [1, 3, 4, 6]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"insertionSort([6, 3, 4, 1]); // [1, 3, 4, 6]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-invert-object-key-value-pairs":{"intro":"In this lab, we will explore how to invert an object's key-value pairs without mutating the original object. We will use the Object.keys() method and Array.prototype.reduce() to invert the object. Additionally, we will learn how to apply a function to the inverted keys and return an array of keys responsible for generating the inverted value.","steps":[{"title":"Invert Object","body":["To invert the key-value pairs of an object without altering the original object, use the invertKeyValues function.","• The Object.keys() and Array.prototype.reduce() methods are used to create a new object with inverted key-value pairs, and if a function is provided, it is applied to each inverted key.","• If fn is omitted, the function returns only the inverted keys without any function applied to them.","• The function returns an object with each inverted value being an array of keys responsible for generating the inverted value."],"code":[{"lang":"js","text":"const invertKeyValues = (obj, fn) =>\n  Object.keys(obj).reduce((acc, key) => {\n    const val = fn ? fn(obj[key]) : obj[key];\n    acc[val] = acc[val] || [];\n    acc[val].push(key);\n    return acc;\n  }, {});"},{"lang":"js","text":"invertKeyValues({ a: 1, b: 2, c: 1 }); // { 1: [ 'a', 'c' ], 2: [ 'b' ] }\ninvertKeyValues({ a: 1, b: 2, c: 1 }, (value) => \"group\" + value);\n// { group1: [ 'a', 'c' ], group2: [ 'b' ] }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"invertKeyValues({ a: 1, b: 2, c: 1 }); // { 1: [ 'a', 'c' ], 2: [ 'b' ] }\ninvertKeyValues({ a: 1, b: 2, c: 1 }, (value) => \"group\" + value);\n// { group1: [ 'a', 'c' ], group2: [ 'b' ] }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-string-is-alphanumeric":{"intro":"In this lab, we will explore how to check if a given string contains only alphanumeric characters using JavaScript. We will use a regular expression pattern to match the input string against alphanumeric characters and return a boolean value indicating whether the string is alphanumeric or not. This lab will help you understand how to work with regular expressions in JavaScript and how to use them to solve practical problems.","steps":[{"title":"Understanding Alphanumeric Characters","body":["Understanding Alphanumeric Characters","Alphanumeric characters consist of the 26 letters in the English alphabet (both uppercase A-Z and lowercase a-z) and the 10 numerical digits (0-9). When we check if a string is alphanumeric, we are verifying that it contains only these characters and nothing else.","In JavaScript, we can check for alphanumeric characters using regular expressions. Regular expressions (regex) are patterns used to match character combinations in strings.","Let's start by opening our code editor. In the WebIDE, navigate to the file explorer on the left side and create a new JavaScript file:"],"code":[{"lang":"javascript","text":"// Function to check if a string is alphanumeric\nfunction isAlphaNumeric(str) {\n  // Using regular expression to check for alphanumeric characters\n  return /^[a-zA-Z0-9]+$/.test(str);\n}\n\n// Example usage\nconsole.log(\"Is 'hello123' alphanumeric?\", isAlphaNumeric(\"hello123\"));\nconsole.log(\"Is '123' alphanumeric?\", isAlphaNumeric(\"123\"));\nconsole.log(\"Is 'hello 123' alphanumeric?\", isAlphaNumeric(\"hello 123\"));\nconsole.log(\"Is 'hello@123' alphanumeric?\", isAlphaNumeric(\"hello@123\"));"},{"lang":"bash","text":"node alphanumeric.js"},{"lang":"text","text":"Is 'hello123' alphanumeric? true\nIs '123' alphanumeric? true\nIs 'hello 123' alphanumeric? false\nIs 'hello@123' alphanumeric? false"}]},{"title":"Understanding Regular Expressions","body":["Understanding Regular Expressions","Now let's examine the regular expression we used in our function:","This pattern might look complex, but we can break it down into parts:","• / - The forward slashes mark the beginning and end of the regular expression pattern. • ^ - This symbol means \"start of the string\". • [a-zA-Z0-9] - This is a character class that matches: • a-z: any lowercase letter from 'a' to 'z' • A-Z: any uppercase letter from 'A' to 'Z' • 0-9: any digit from '0' to '9' • + - This quantifier means \"one or more\" of the preceding element. • $ - This symbol means \"end of the string\"."],"code":[{"lang":"javascript","text":"/^[a-zA-Z0-9]+$/;"},{"lang":"javascript","text":"// Function to check if a string is alphanumeric\nfunction isAlphaNumeric(str) {\n  return /^[a-zA-Z0-9]+$/.test(str);\n}\n\n// Alternative function using case-insensitive flag\nfunction isAlphaNumericAlt(str) {\n  return /^[a-z0-9]+$/i.test(str);\n}\n\n// Example usage\nconsole.log(\"Using first function:\");\nconsole.log(\"Is 'Hello123' alphanumeric?\", isAlphaNumeric(\"Hello123\"));\nconsole.log(\"Is 'HELLO123' alphanumeric?\", isAlphaNumeric(\"HELLO123\"));\n\nconsole.log(\"\\nUsing alternative function with case-insensitive flag:\");\nconsole.log(\"Is 'Hello123' alphanumeric?\", isAlphaNumericAlt(\"Hello123\"));\nconsole.log(\"Is 'HELLO123' alphanumeric?\", isAlphaNumericAlt(\"HELLO123\"));"},{"lang":"bash","text":"node alphanumeric.js"}]},{"title":"Creating a Simple Validation Tool","body":["Creating a Simple Validation Tool","Create a new file named validator.js in the same directory:","Add the following code to the file:","Save the file and run it with:"],"code":[{"lang":"javascript","text":"const readline = require(\"readline\");\n\n// Create a readline interface for user input\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout\n});\n\n// Function to check if a string is alphanumeric\nfunction isAlphaNumeric(str) {\n  return /^[a-zA-Z0-9]+$/.test(str);\n}\n\n// Function to check the input\nfunction checkInput(input) {\n  if (isAlphaNumeric(input)) {\n    console.log(`\"${input}\" is alphanumeric.`);\n  } else {\n    console.log(`\"${input}\" is NOT alphanumeric.`);\n    console.log(\n      \"Alphanumeric strings contain only letters (A-Z, a-z) and numbers (0-9).\"\n    );\n  }\n\n  // Ask if the user wants to check another string\n  rl.question(\"\\nDo you want to check another string? (yes/no): \", (answer) => {\n    if (answer.toLowerCase() === \"yes\" || answer.toLowerCase() === \"y\") {\n      askForInput();\n    } else {\n      console.log(\"Thank you for using the alphanumeric validator!\");\n      rl.close();\n    }\n  });\n}\n\n// Function to ask for input\nfunction askForInput() {\n  rl.question(\"Enter a string to check if it is alphanumeric: \", (input) => {\n    checkInput(input);\n  });\n}\n\n// Welcome message\nconsole.log(\"=== Alphanumeric String Validator ===\");\nconsole.log(\n  \"This tool checks if a string contains only alphanumeric characters (A-Z, a-z, 0-9).\\n\"\n);"},{"lang":"bash","text":"node validator.js"}]},{"title":"Exploring Other Ways to Check Alphanumeric Strings","body":["Exploring Other Ways to Check Alphanumeric Strings","Besides using regular expressions, there are other methods to check if a string is alphanumeric. Let's explore some of them by creating a new file named alternative-methods.js:","Add the following code to the file:","Save the file and run it with:"],"code":[{"lang":"javascript","text":"// Method 1: Using regular expression (our original method)\nfunction isAlphaNumericRegex(str) {\n  return /^[a-zA-Z0-9]+$/.test(str);\n}\n\n// Method 2: Using Array.every() and checking each character\nfunction isAlphaNumericEvery(str) {\n  // If string is empty, return false\n  if (str.length === 0) return false;\n\n  return [...str].every((char) => {\n    const code = char.charCodeAt(0);\n    // Check if character is a digit (0-9)\n    const isDigit = code >= 48 && code <= 57;\n    // Check if character is a lowercase letter (a-z)\n    const isLowercase = code >= 97 && code <= 122;\n    // Check if character is an uppercase letter (A-Z)\n    const isUppercase = code >= 65 && code <= 90;\n\n    return isDigit || isLowercase || isUppercase;\n  });\n}\n\n// Method 3: Using a combination of match() and length\nfunction isAlphaNumericMatch(str) {\n  // If string is empty, return false\n  if (str.length === 0) return false;\n\n  // Remove all alphanumeric characters and check if anything remains\n  const nonAlphaNumeric = str.match(/[^a-zA-Z0-9]/g);\n  return nonAlphaNumeric === null;\n}\n\n// Test strings\nconst testStrings = [\n  \"hello123\",\n  \"HELLO123\",\n  \"hello 123\",\n  \"hello@123\",\n  \"\",\n  \"0123456789\",\n  \"abcdefghijklmnopqrstuvwxyz\"\n];\n\n// Test each method with each string\nconsole.log(\"=== Testing Different Methods ===\");\nconsole.log(\"String\\t\\t\\tRegex\\tEvery\\tMatch\");\nconsole.log(\"---------------------------------------------\");"},{"lang":"bash","text":"node alternative-methods.js"}]}],"commands":["node alphanumeric.js","node validator.js","node alternative-methods.js"],"reference":[{"path":"reference.sh","text":"node alternative-methods.js"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-value-is-array-like":{"intro":"In this lab, we will explore the concept of array-like objects in JavaScript and learn how to determine whether an object is iterable. We will use the isArrayLike function to check if an object has an iterator and therefore can be iterated over using a for...of loop. By the end of this lab, you will have a better understanding of how to work with array-like objects in JavaScript.","steps":[{"title":"Value Is Array-Like","body":["To check if a value is array-like, follow these steps:","• The function will return true if the provided argument is an array-like object, and false otherwise. • For example:"],"code":[{"lang":"js","text":"const isArrayLike = (obj) =>\n  obj != null && typeof obj[Symbol.iterator] === \"function\";"},{"lang":"js","text":"isArrayLike([1, 2, 3]); // true\nisArrayLike(document.querySelectorAll(\".className\")); // true\nisArrayLike(\"abc\"); // true\nisArrayLike(null); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isArrayLike([1, 2, 3]); // true\nisArrayLike(document.querySelectorAll(\".className\")); // true\nisArrayLike(\"abc\"); // true\nisArrayLike(null); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-value-is-async-function":{"intro":"In this lab, we will explore the concept of asynchronous functions in JavaScript. We will learn how to recognize and differentiate between regular functions and async functions using the isAsyncFunction() method. By the end of this lab, you will have a clear understanding of how to work with asynchronous functions and how they can be used to improve the performance of your code.","steps":[{"title":"Value Is Async Function","body":["Check if a Value is an Async Function in JavaScript","To check if a value is an async function in JavaScript, you can use the following code:","This function uses Object.prototype.toString() and Function.prototype.call() to check whether the given argument is an async function.","You can test the function by passing a regular function and an async function as arguments:"],"code":[{"lang":"js","text":"const isAsyncFunction = (val) =>\n  Object.prototype.toString.call(val) === \"[object AsyncFunction]\";"},{"lang":"js","text":"isAsyncFunction(function () {}); // false\nisAsyncFunction(async function () {}); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isAsyncFunction(function () {}); // false\nisAsyncFunction(async function () {}); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-value-is-boolean":{"intro":"In this lab, we will dive into the concept of boolean values in JavaScript. We will explore how to check whether a given value is a boolean primitive or not using the typeof operator. By the end of this lab, you will have a solid understanding of how to identify boolean values in JavaScript.","steps":[{"title":"Value Is Boolean","body":["Checking if a Value is Boolean","To check if a value is a boolean primitive in JavaScript, use the typeof operator with the === comparison operator.","Here's an example of how to use isBoolean() function to check if a value is boolean:"],"code":[{"lang":"js","text":"const isBoolean = (val) => typeof val === \"boolean\";"},{"lang":"js","text":"isBoolean(null); // returns false\nisBoolean(false); // returns true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isBoolean(null); // returns false\nisBoolean(false); // returns true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-date-is-valid":{"intro":"In this lab, we will explore a JavaScript function that checks whether a given date is valid or not. The function uses the spread operator and the Date constructor to create a new Date object from the given arguments. It then uses the valueOf() method and Number.isNaN() to check if the object is valid. This lab is a great opportunity to practice working with JavaScript functions and date objects.","steps":[{"title":"Check if Date Is Valid","body":["How to Check if a Date Is Valid","To check if a date is valid, follow these steps:","Here's an example code snippet:","You can test the function with different values, as shown below:"],"code":[{"lang":"js","text":"const isDateValid = (...val) => !Number.isNaN(new Date(...val).valueOf());"},{"lang":"js","text":"isDateValid(\"December 17, 1995 03:24:00\"); // true\nisDateValid(\"1995-12-17T03:24:00\"); // true\nisDateValid(\"1995-12-17 T03:24:00\"); // false\nisDateValid(\"Duck\"); // false\nisDateValid(1995, 11, 17); // true\nisDateValid(1995, 11, 17, \"Duck\"); // false\nisDateValid({}); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isDateValid(\"December 17, 1995 03:24:00\"); // true\nisDateValid(\"1995-12-17T03:24:00\"); // true\nisDateValid(\"1995-12-17 T03:24:00\"); // false\nisDateValid(\"Duck\"); // false\nisDateValid(1995, 11, 17); // true\nisDateValid(1995, 11, 17, \"Duck\"); // false\nisDateValid({}); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-object-is-deep-frozen":{"intro":"In this lab, we will learn how to check if an object is deeply frozen in JavaScript. The lab will guide us through a recursive function that uses Object.isFrozen() to determine if an object is frozen and Object.keys() with Array.prototype.every() to check all keys for deep freezing. By the end of this lab, we will have a better understanding of how to determine the deep freezing status of an object in JavaScript.","steps":[{"title":"Check if Object Is Deep Frozen","body":["How to Check if an Object is Deeply Frozen","To check if an object is deeply frozen, use the following steps in JavaScript:","Here's an example code snippet to check if an object is deeply frozen:","You can use the isDeepFrozen function to check if an object is deeply frozen like this:"],"code":[{"lang":"js","text":"const isDeepFrozen = (obj) =>\n  Object.isFrozen(obj) &&\n  Object.keys(obj).every(\n    (prop) => typeof obj[prop] !== \"object\" || isDeepFrozen(obj[prop])\n  );"},{"lang":"js","text":"const x = Object.freeze({ a: 1 });\nconst y = Object.freeze({ b: { c: 2 } });\nisDeepFrozen(x); // true\nisDeepFrozen(y); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const x = Object.freeze({ a: 1 });\nconst y = Object.freeze({ b: { c: 2 } });\nisDeepFrozen(x); // true\nisDeepFrozen(y); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-stream-is-duplex":{"intro":"In this lab, we will explore how to determine whether a given argument is a duplex (readable and writable) stream in JavaScript. We will use a combination of typeof checks and property validations to create a function that can accurately identify duplex streams. By the end of this lab, you will have a better understanding of how streams work in JavaScript and how to work with them in your own code.","steps":[{"title":"Stream Is Duplex","body":["Checking if a Stream is Duplex","• Check if the given argument is different from null. • Use typeof to check if the given argument is of type object and if it has a pipe property of type function. • Additionally, check if the _read, _write, _readableState, and _writableState properties are of type function and object, respectively.","You can test this code using the following example:"],"code":[{"lang":"js","text":"const isDuplexStream = (val) =>\n  val !== null &&\n  typeof val === \"object\" &&\n  typeof val.pipe === \"function\" &&\n  typeof val._read === \"function\" &&\n  typeof val._readableState === \"object\" &&\n  typeof val._write === \"function\" &&\n  typeof val._writableState === \"object\";"},{"lang":"js","text":"const Stream = require(\"stream\");\n\nisDuplexStream(new Stream.Duplex()); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const Stream = require(\"stream\");\n\nisDuplexStream(new Stream.Duplex()); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-number-is-even":{"intro":"In this lab, we will delve into the world of JavaScript programming and learn how to write a function to determine whether a given number is even or odd. The lab will guide you through the steps of using the modulo operator to check whether a number is divisible by 2, and then returning true if it is even, or false if it is odd. By the end of this lab, you will have a better understanding of basic programming concepts in JavaScript and how to write functions for simple tasks.","steps":[{"title":"Number Is Even","body":["The code above uses the modulo (%) operator to check whether a number is odd or even. If the number is even, the function returns true. If it's odd, the function returns false.","Here is an example of how to use the isEven function:"],"code":[{"lang":"js","text":"const isEven = (num) => num % 2 === 0;"},{"lang":"js","text":"isEven(3); // returns false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isEven(3); // returns false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-value-is-generator-function":{"intro":"In this lab, we will delve into the concept of generator functions in JavaScript. We will explore how they differ from regular functions and learn how to identify them using the isGeneratorFunction() function. Through practical examples and exercises, you will gain a solid understanding of how generator functions work and their potential applications in your code.","steps":[{"title":"Value Is Generator Function","body":["Checking if a Value is a Generator Function","Here's how the isGeneratorFunction function works:","• It checks if the given argument is a generator function by using Object.prototype.toString() and Function.prototype.call(). • If the result of the check is '[object GeneratorFunction]', then the value is a generator function.","Here's the code for the isGeneratorFunction function:"],"code":[{"lang":"js","text":"const isGeneratorFunction = (val) =>\n  Object.prototype.toString.call(val) === \"[object GeneratorFunction]\";"},{"lang":"js","text":"isGeneratorFunction(function () {}); // false\nisGeneratorFunction(function* () {}); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isGeneratorFunction(function () {}); // false\nisGeneratorFunction(function* () {}); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-string-is-iso-formatted-date":{"intro":"In this lab, we will explore how to determine if a given string is a valid date string in the simplified extended ISO format (ISO 8601). We will use the Date constructor and its associated methods to create a Date object from the string and check its validity. By the end of the lab, you will have a better understanding of how to work with dates in JavaScript and how to validate them using the ISO format.","steps":[{"title":"Understanding ISO Date Format and JavaScript Date Objects","body":["Understanding ISO Date Format and JavaScript Date Objects","Before we start coding, let us understand what the ISO 8601 date format is and how JavaScript handles dates.","The ISO 8601 format is an international standard for representing dates and times. The simplified extended ISO format looks like this:","• YYYY represents the year (four digits) • MM represents the month (two digits) • DD represents the day (two digits) • T is a literal character separating the date and time • HH represents hours (two digits) • mm represents minutes (two digits) • ss represents seconds (two digits) • sss represents milliseconds (three digits) • Z indicates UTC timezone (Zulu time)"],"code":[{"lang":"text","text":"YYYY-MM-DDTHH:mm:ss.sssZ"},{"lang":"javascript","text":"const date = new Date(\"2023-05-12T14:30:15.123Z\");"},{"lang":"javascript","text":"const now = new Date();\nconsole.log(now);"}]},{"title":"Creating a Function to Validate ISO Formatted Date Strings","body":["Creating a Function to Validate ISO Formatted Date Strings","In this step, we will create a JavaScript function that checks if a given string is in valid ISO 8601 format.","Creating the Validation Function","Let us create a new JavaScript file for our ISO date validator:"],"code":[{"lang":"javascript","text":"/**\n * Checks if a string is a valid ISO 8601 formatted date string\n * @param {string} val - The string to check\n * @return {boolean} - Returns true if the string is in ISO format, false otherwise\n */\nconst isISOString = (val) => {\n  // Create a Date object from the input string\n  const d = new Date(val);\n\n  // Check if the date is valid (not NaN) and if the ISO string matches the original\n  return !Number.isNaN(d.valueOf()) && d.toISOString() === val;\n};\n\n// Export the function so we can use it elsewhere\nmodule.exports = isISOString;"},{"lang":"javascript","text":"// Import our isISOString function\nconst isISOString = require(\"./isISODate\");\n\n// Test with a valid ISO formatted date\nconsole.log(\"Testing a valid ISO date:\");\nconsole.log(\"2020-10-12T10:10:10.000Z\");\nconsole.log(\"Result:\", isISOString(\"2020-10-12T10:10:10.000Z\"));\nconsole.log();\n\n// Test with an invalid format\nconsole.log(\"Testing a non-ISO date:\");\nconsole.log(\"2020-10-12\");\nconsole.log(\"Result:\", isISOString(\"2020-10-12\"));"},{"lang":"bash","text":"node testISO.js"}]},{"title":"Testing with Various Date Formats","body":["Testing with Various Date Formats","Now that we have our basic validation function, let us test it with different date formats to understand how it behaves with various inputs.","Let us create a comprehensive test suite to examine different date formats:","• Create a new file named dateTester.js • Add the following code:"],"code":[{"lang":"javascript","text":"// Import our isISOString function\nconst isISOString = require(\"./isISODate\");\n\n// Function to test different date strings\nfunction testDate(description, dateString) {\n  console.log(`Testing: ${description}`);\n  console.log(`Input: \"${dateString}\"`);\n  console.log(`Is ISO Format: ${isISOString(dateString)}`);\n  console.log(\"-----------------------\");\n}\n\n// Valid ISO date examples\ntestDate(\"Standard ISO date with timezone Z\", \"2023-05-12T14:30:15.123Z\");\ntestDate(\"ISO date with zero milliseconds\", \"2020-10-12T10:10:10.000Z\");\n\n// Invalid or non-ISO format examples\ntestDate(\"Date only (no time component)\", \"2023-05-12\");\ntestDate(\"Date and time without milliseconds\", \"2023-05-12T14:30:15Z\");\ntestDate(\n  \"Date with time zone offset instead of Z\",\n  \"2023-05-12T14:30:15+01:00\"\n);\ntestDate(\"Invalid date (month 13 does not exist)\", \"2023-13-12T14:30:15.123Z\");\ntestDate(\"Non-date string\", \"Hello World\");"},{"lang":"bash","text":"node dateTester.js"}]},{"title":"Handling Edge Cases and Improving Our Function","body":["Handling Edge Cases and Improving Our Function","In this final step, we will improve our isISOString function to handle edge cases and make it more robust.","When validating data in real applications, you need to handle various unexpected inputs. Let us examine some edge cases:","• Empty strings • Non-string values (null, undefined, numbers, objects) • Different timezone representations"],"code":[{"lang":"javascript","text":"/**\n * Checks if a string is a valid ISO 8601 formatted date string\n * @param {string} val - The string to check\n * @return {boolean} - Returns true if the string is in ISO format, false otherwise\n */\nconst isISOString = (val) => {\n  // Check if input is a string\n  if (typeof val !== \"string\") {\n    return false;\n  }\n\n  // Check if string is empty\n  if (val.trim() === \"\") {\n    return false;\n  }\n\n  try {\n    // Create a Date object from the input string\n    const d = new Date(val);\n\n    // Check if the date is valid and if the ISO string matches the original\n    return !Number.isNaN(d.valueOf()) && d.toISOString() === val;\n  } catch (error) {\n    // If any error occurs during validation, return false\n    return false;\n  }\n};\n\n// Export the function\nmodule.exports = isISOString;"},{"lang":"javascript","text":"// Import our improved isISOString function\nconst isISOString = require(\"./isISODate\");\n\n// Function to test and display results\nfunction testCase(description, value) {\n  console.log(`Testing: ${description}`);\n  console.log(`Input: ${value === \"\" ? \"(empty string)\" : value}`);\n  console.log(`Type: ${typeof value}`);\n  console.log(`Is ISO Format: ${isISOString(value)}`);\n  console.log(\"-----------------------\");\n}\n\n// Test with various edge cases\ntestCase(\"Valid ISO date\", \"2023-05-12T14:30:15.123Z\");\ntestCase(\"Empty string\", \"\");\ntestCase(\"Null value\", null);\ntestDate(\"Undefined value\", undefined);\ntestCase(\"Number value\", 12345);\ntestCase(\"Object value\", {});\ntestCase(\"Current date as ISO string\", new Date().toISOString());"},{"lang":"bash","text":"node edgeCaseTester.js"}]}],"commands":["node testISO.js","node dateTester.js","node edgeCaseTester.js"],"reference":[{"path":"reference.sh","text":"node edgeCaseTester.js"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-for-leap-year":{"intro":"In this lab, we will explore the fundamental concepts of JavaScript programming. Through a series of exercises, you will learn how to write basic JavaScript programs, including variables, data types, functions, and control flow structures. By the end of the lab, you will have a solid foundation in JavaScript programming and be able to apply your knowledge to solve real-world problems.","steps":[{"title":"Check for Leap Year","body":["To check if a given year is a leap year, follow these steps:","Here is an example of how to use this code:"],"code":[{"lang":"js","text":"const isLeapYear = (year) => new Date(year, 1, 29).getMonth() === 1;"},{"lang":"js","text":"isLeapYear(2019); // false\nisLeapYear(2020); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isLeapYear(2019); // false\nisLeapYear(2020); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-string-is-lowercase":{"intro":"In this lab, we will explore the concept of checking if a given string is in lowercase or not using JavaScript. We will learn about the String.prototype.toLowerCase() method, which is used to convert a given string to lowercase. By the end of this lab, you will be able to write a function that checks if a string is in lowercase or not.","steps":[{"title":"String Is Lowercase","body":["JavaScript Function to Check if a String is Lowercase","To check if a given string is lowercase, you can use the following JavaScript function. First, convert the string to lowercase using String.prototype.toLowerCase() and then compare it to the original string using strict equality (===)."],"code":[{"lang":"js","text":"const isLowerCase = (str) => str === str.toLowerCase();"},{"lang":"js","text":"isLowerCase(\"abc\"); // true\nisLowerCase(\"a3@$\"); // true\nisLowerCase(\"Ab4\"); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isLowerCase(\"abc\"); // true\nisLowerCase(\"a3@$\"); // true\nisLowerCase(\"Ab4\"); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-value-is-object":{"intro":"In this lab, we will explore the isObject function in JavaScript. The function checks whether a given value is an object or not by creating an object wrapper for the value using the Object constructor. We will learn how to use this function to determine the type of values and understand its implementation in various scenarios.","steps":[{"title":"Value Is Object","body":["Determining if Value is an Object","• The Object constructor creates an object wrapper for the given value. • If the value is null or undefined, an empty object is created and returned. • If the value is not null or undefined, an object of a type corresponding to the given value is returned.","Here is an example function that checks if a value is an object:","Here are some examples of using the isObject function:"],"code":[{"lang":"js","text":"const isObject = (obj) => obj === Object(obj);"},{"lang":"js","text":"isObject([1, 2, 3, 4]); // true\nisObject([]); // true\nisObject([\"Hello!\"]); // true\nisObject({ a: 1 }); // true\nisObject({}); // true\nisObject(true); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isObject([1, 2, 3, 4]); // true\nisObject([]); // true\nisObject([\"Hello!\"]); // true\nisObject({ a: 1 }); // true\nisObject({}); // true\nisObject(true); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"}};
